//! Un exemple JSON par variante du catalogue (conditions, actions, déclencheurs), pour vérifier que tout est lisible.

pub const CONDITIONS: &str = r##"[{"type": "name", "matcher": {"op": "contains", "value": "a"}}, {"type": "stem", "matcher": {"op": "contains", "value": "a"}}, {"type": "extension", "in_list": ["a"]}, {"type": "name_length", "cmp": "gt", "n": 1}, {"type": "name_has_spaces"}, {"type": "name_has_uppercase"}, {"type": "name_has_accents"}, {"type": "name_has_date_like"}, {"type": "path", "matcher": {"op": "contains", "value": "a"}}, {"type": "parent_name", "matcher": {"op": "contains", "value": "a"}}, {"type": "in_folder", "path": "a"}, {"type": "depth", "cmp": "gt", "n": 1}, {"type": "inside_git_repo"}, {"type": "inside_trash"}, {"type": "is_file"}, {"type": "is_folder"}, {"type": "is_symlink"}, {"type": "is_broken_symlink"}, {"type": "is_hidden"}, {"type": "is_executable"}, {"type": "is_read_only"}, {"type": "is_empty"}, {"type": "is_mount_point"}, {"type": "kind", "in_list": ["image"]}, {"type": "mime", "matcher": {"op": "contains", "value": "a"}}, {"type": "size", "cmp": "gt", "bytes": 1}, {"type": "folder_total_size", "cmp": "gt", "bytes": 1}, {"type": "child_count", "cmp": "gt", "n": 1}, {"type": "file_count", "cmp": "gt", "n": 1}, {"type": "modified_before", "at": 1.0}, {"type": "modified_after", "at": 1.0}, {"type": "modified_within", "duration": {"n": 1, "unit": "days"}}, {"type": "older_than", "duration": {"n": 1, "unit": "days"}}, {"type": "created_before", "at": 1.0}, {"type": "created_after", "at": 1.0}, {"type": "accessed_older_than", "duration": {"n": 1, "unit": "days"}}, {"type": "modified_on_weekday", "days": ["mon"]}, {"type": "modified_in_month", "months": [1]}, {"type": "modified_in_year", "years": [2024]}, {"type": "never_opened"}, {"type": "text_contains", "matcher": {"op": "contains", "value": "a"}}, {"type": "line_count", "cmp": "gt", "n": 1}, {"type": "first_line", "matcher": {"op": "contains", "value": "a"}}, {"type": "has_shebang"}, {"type": "encoding", "value": "utf8"}, {"type": "image_width", "cmp": "gt", "px": 1}, {"type": "image_height", "cmp": "gt", "px": 1}, {"type": "orientation", "value": "square"}, {"type": "megapixels", "cmp": "gt", "n": 1.0}, {"type": "has_alpha"}, {"type": "duration", "cmp": "gt", "seconds": 1.0}, {"type": "video_resolution", "cmp": "gt", "px": 1}, {"type": "has_audio_track"}, {"type": "archive_is_readable"}, {"type": "archive_entry_count", "cmp": "gt", "n": 1}, {"type": "archive_contains_name", "matcher": {"op": "contains", "value": "a"}}, {"type": "archive_is_encrypted"}, {"type": "duplicate_of_another", "scope": "folder"}, {"type": "is_newest_of_duplicates", "scope": "folder"}, {"type": "is_oldest_of_duplicates", "scope": "folder"}, {"type": "same_name_as", "scope": "folder"}, {"type": "git_status", "in_list": ["modified"]}, {"type": "downloaded_from", "matcher": {"op": "contains", "value": "a"}}, {"type": "from_disk", "disk": "a"}, {"type": "free_space_below", "bytes": 1, "on": "disk"}, {"type": "disk_is_mounted", "disk": "a"}, {"type": "owned_by_me"}, {"type": "permissions", "mode": 420}, {"type": "is_favorite"}, {"type": "in_recents"}, {"type": "is_pinned_folder"}, {"type": "all_of", "tests": []}, {"type": "any_of", "tests": []}, {"type": "none_of", "tests": []}]"##;
pub const ACTIONS: &str = r##"[{"type": "move_to", "folder": "a"}, {"type": "copy_to", "folder": "a"}, {"type": "move_to_dated", "folder": "a", "pattern": "{year}"}, {"type": "move_to_by_kind", "base": "a"}, {"type": "move_to_by_extension", "base": "a"}, {"type": "rename", "template": "{name}"}, {"type": "replace_in_name", "find": "a", "replace": "b"}, {"type": "change_case", "mode": "lower"}, {"type": "slugify"}, {"type": "add_prefix", "text": "a"}, {"type": "add_suffix", "text": "a"}, {"type": "add_date", "from": "modified", "position": "prefix", "format": "AAAA"}, {"type": "add_counter", "start": 1, "width": 2}, {"type": "remove_spaces"}, {"type": "normalize_extension"}, {"type": "trash"}, {"type": "trash_duplicates", "keep": "newest"}, {"type": "empty_trash_older_than", "duration": {"n": 1, "unit": "days"}}, {"type": "remove_empty_folders"}, {"type": "zip", "mode": "one_per_item"}, {"type": "unzip", "then": "keep"}, {"type": "zip_folder_then_trash"}, {"type": "create_folder", "template": "a"}, {"type": "flatten_folder"}, {"type": "set_read_only", "value": true}, {"type": "set_executable", "value": true}, {"type": "set_permissions", "mode": 420}, {"type": "set_modified_time", "from": "today"}, {"type": "pin_folder_in_sidebar"}, {"type": "add_to_favorites"}, {"type": "remove_from_favorites"}, {"type": "hide", "value": true}, {"type": "open_with_default"}, {"type": "reveal_in_five_folder"}, {"type": "notify", "message_template": "a"}, {"type": "notify_only_once"}, {"type": "stop_processing"}, {"type": "skip_remaining_actions"}, {"type": "wait_stable", "for": {"n": 5, "unit": "seconds"}}, {"type": "log_only"}]"##;
pub const TRIGGERS: &str = r##"[{"type": "created"}, {"type": "modified"}, {"type": "moved_in"}, {"type": "stable", "for": {"n": 5, "unit": "seconds"}}, {"type": "schedule", "every": {"n": 5, "unit": "minutes"}}, {"type": "daily", "at": "08:30"}, {"type": "weekly", "day": "mon", "at": "08:30"}, {"type": "on_start"}, {"type": "on_mount", "disk": "a"}, {"type": "manual"}]"##;
